def main():
    root=Path(__file__).resolve().parent
    package=root/'Automation' if (root/'Automation/Common_Rules').is_dir() else root
    if not (package/'Read_Invoice_V3.py').is_file():raise SystemExit('Install_Invoice_Workflow_V3.py must be run first.')
    folder=root/'.invoice_app/web50_benchmark/sources';folder.mkdir(parents=True,exist_ok=True)
    for case in CASES:
        target=folder/(case['case_id']+'.pdf')
        if target.exists():
            if hashlib.sha256(target.read_bytes()).hexdigest()==case['sha256']:continue
            raise SystemExit('An existing sample has different contents; it was preserved.')
        parts=urlparse(case['source_url'])
        if parts.netloc!='github.com' or '/blob/HEAD/' not in parts.path:raise SystemExit('Unsupported frozen public source URL.')
        owner,repo,_,_,*path=parts.path.strip('/').split('/')
        url='https://raw.githubusercontent.com/'+owner+'/'+repo+'/HEAD/'+quote('/'.join(path),safe='/')
        print('Downloading public case '+case['case_id'],flush=True)
        try:
            with urlopen(url,timeout=30) as stream:data=stream.read(8*1024*1024+1)
        except Exception:raise SystemExit('Public source download failed. No AI request or Tally import was sent.')
        if not data.startswith(b'%PDF') or hashlib.sha256(data).hexdigest()!=case['sha256']:
            raise SystemExit('Public sample changed or failed verification. Existing files were preserved.')
        with target.open('wb') as stream:stream.write(data)
    (folder.parent/'Public_Cases.json').write_text(json.dumps(CASES,ensure_ascii=True,indent=2),encoding='utf-8')
    choices=[package/'.venv/Scripts/python.exe',root/'.venv/Scripts/python.exe',package/'.venv/bin/python',root/'.venv/bin/python']
    python=next((str(p) for p in choices if p.is_file()),sys.executable)
    args=sys.argv[1:]
    raise SystemExit(subprocess.run([python,str(package/'Read_Invoice_V3.py'),str(folder),'--xml',*args],cwd=root).returncode)

if __name__=='__main__':main()
